package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.ServletException; import java.io.IOException; import java.sql.*; import java.math.BigDecimal;
@WebServlet("/checkout")
public class CheckoutServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/checkout.jsp").forward(q,r);}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try(Connection c=DB.getConnection()){c.setAutoCommit(false);try{BigDecimal total=BigDecimal.ZERO;try(PreparedStatement s=c.prepareStatement("SELECT c.product_id,c.quantity,p.price,p.discount,p.stock FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=? FOR UPDATE")){s.setInt(1,u.getUserId());try(ResultSet rs=s.executeQuery()){while(rs.next()){int qty=rs.getInt("quantity");if(qty>rs.getInt("stock"))throw new IllegalArgumentException("Not enough stock for one or more products.");BigDecimal unit=rs.getBigDecimal("price").multiply(BigDecimal.ONE.subtract(rs.getBigDecimal("discount").divide(new BigDecimal("100"))));total=total.add(unit.multiply(BigDecimal.valueOf(qty)));}}}
 if(total.signum()<=0)throw new IllegalArgumentException("Your cart is empty.");
 int orderId;try(PreparedStatement s=c.prepareStatement("INSERT INTO orders(user_id,total_amount,payment_method,payment_status,order_status) VALUES(?,?,'MOCK','PAID','PLACED')",Statement.RETURN_GENERATED_KEYS)){s.setInt(1,u.getUserId());s.setBigDecimal(2,total);s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();orderId=k.getInt(1);}}
 try(PreparedStatement get=c.prepareStatement("SELECT c.product_id,c.quantity,p.price,p.discount FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=?");PreparedStatement item=c.prepareStatement("INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)");PreparedStatement stock=c.prepareStatement("UPDATE products SET stock=stock-? WHERE product_id=?");PreparedStatement clear=c.prepareStatement("DELETE FROM cart WHERE user_id=?");PreparedStatement payment=c.prepareStatement("INSERT INTO payments(order_id,payment_method,transaction_reference,amount,payment_status) VALUES(?,'MOCK',?,?, 'SUCCESS')")){get.setInt(1,u.getUserId());try(ResultSet rs=get.executeQuery()){while(rs.next()){int pid=rs.getInt("product_id"),qty=rs.getInt("quantity");BigDecimal price=rs.getBigDecimal("price").multiply(BigDecimal.ONE.subtract(rs.getBigDecimal("discount").divide(new BigDecimal("100"))));item.setInt(1,orderId);item.setInt(2,pid);item.setInt(3,qty);item.setBigDecimal(4,price);item.addBatch();stock.setInt(1,qty);stock.setInt(2,pid);stock.addBatch();}}item.executeBatch();stock.executeBatch();clear.setInt(1,u.getUserId());clear.executeUpdate();payment.setInt(1,orderId);payment.setString(2,"MOCK-"+orderId);payment.setBigDecimal(3,total);payment.executeUpdate();}
 c.commit();r.sendRedirect(q.getContextPath()+"/orders?placed="+orderId);
 }catch(Exception ex){c.rollback();if(ex instanceof IllegalArgumentException){q.setAttribute("error",ex.getMessage());q.getRequestDispatcher("/WEB-INF/views/checkout.jsp").forward(q,r);return;}throw ex;}finally{c.setAutoCommit(true);}}catch(Exception e){throw new ServletException("Checkout failed.",e);}}
}
